(() => {
  'use strict';
  const $ = selector => document.querySelector(selector);
  const header = $('.site-header');
  if (header) {
    const sectionLinks = [...header.querySelectorAll('[data-header-section]')]
      .map(link => ({ link, section: document.querySelector(link.getAttribute('href')) }))
      .filter(item => item.section);
    let headerFrame = null;
    const updateHeader = () => {
      headerFrame = null;
      const height = header.getBoundingClientRect().height;
      document.documentElement.style.setProperty('--header-offset', `${height + 16}px`);
      const readingLine = height + Math.min(120, Math.max(24, (window.innerHeight - height) * .2));
      const current = sectionLinks.find(({ section }) => {
        const bounds = section.getBoundingClientRect();
        return bounds.top <= readingLine && bounds.bottom > readingLine;
      });
      sectionLinks.forEach(item => {
        if (item === current) item.link.setAttribute('aria-current', 'location');
        else item.link.removeAttribute('aria-current');
      });
    };
    const scheduleHeader = () => {
      if (headerFrame === null) headerFrame = requestAnimationFrame(updateHeader);
    };
    window.addEventListener('scroll', scheduleHeader, { passive: true });
    window.addEventListener('resize', scheduleHeader);
    window.addEventListener('pageshow', scheduleHeader);
    if (typeof ResizeObserver !== 'undefined') new ResizeObserver(scheduleHeader).observe(header);
    updateHeader();
  }
  const carousel = $('.fleet-carousel');
  if (carousel) {
    const track = carousel.querySelector('.fleet-track');
    const slides = [...track.querySelectorAll('figure')];
    const dots = [...carousel.querySelectorAll('[data-fleet-slide]')];
    const count = carousel.querySelector('.fleet-count');
    let activeSlide = 0;
    let scrollFrame = null;
    slides.forEach((slide, index) => {
      slide.setAttribute('role', 'group');
      slide.setAttribute('aria-roledescription', 'diapositiva');
      slide.setAttribute('aria-label', `${index + 1} de ${slides.length}`);
    });
    const showSlide = index => {
      activeSlide = (index + slides.length) % slides.length;
      track.scrollTo({
        left: slides[activeSlide].offsetLeft - slides[0].offsetLeft,
        behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'instant' : 'smooth'
      });
    };
    const updatePosition = () => {
      scrollFrame = null;
      const nearest = slides.reduce((best, slide, index) =>
        Math.abs(slide.offsetLeft - slides[0].offsetLeft - track.scrollLeft) <
        Math.abs(slides[best].offsetLeft - slides[0].offsetLeft - track.scrollLeft) ? index : best, 0);
      activeSlide = nearest;
      dots.forEach((dot, index) => {
        if (index === nearest) dot.setAttribute('aria-current', 'true');
        else dot.removeAttribute('aria-current');
      });
      const label = `${nearest + 1} / ${slides.length}`;
      if (count.textContent !== label) count.textContent = label;
    };
    carousel.querySelector('[data-fleet-prev]').addEventListener('click', () => showSlide(activeSlide - 1));
    carousel.querySelector('[data-fleet-next]').addEventListener('click', () => showSlide(activeSlide + 1));
    dots.forEach((dot, index) => dot.addEventListener('click', () => showSlide(index)));
    track.addEventListener('keydown', event => {
      const targets = { ArrowLeft: activeSlide - 1, ArrowRight: activeSlide + 1, Home: 0, End: slides.length - 1 };
      if (!(event.key in targets)) return;
      event.preventDefault();
      showSlide(targets[event.key]);
    });
    track.addEventListener('scroll', () => {
      if (scrollFrame === null) scrollFrame = requestAnimationFrame(updatePosition);
    }, { passive: true });
    window.addEventListener('resize', updatePosition);
    carousel.querySelector('.fleet-controls').hidden = false;
    updatePosition();
  }
  const form = $('#quote-form');
  let whatsappNumber = '';
  const today = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Mexico_City', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
  const events = (event, properties = {}) => {
    // Consent-gated analytics consumes only the explicit fields allowed by analytics.js.
    window.dataLayer = window.dataLayer || [];
    window.dataLayer.push({ event, ...properties });
    window.dispatchEvent(new CustomEvent('renpat:event', { detail: { event, ...properties } }));
  };
  if ($('#year')) $('#year').textContent = new Date().getFullYear();
  if ($('#date')) {
    $('#date').min = today;
    $('#date').max = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Mexico_City', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date(Date.now() + 365 * 86400000));
  }

  let attribution = {};
  try {
    attribution = JSON.parse(sessionStorage.getItem('renpat_attribution') || 'null') || {};
    if (!Object.keys(attribution).length) {
      const params = new URLSearchParams(location.search);
      for (const key of ['utm_source', 'utm_medium', 'utm_campaign', 'utm_content', 'utm_term']) {
        if (params.has(key)) attribution[key] = params.get(key).slice(0, 200);
      }
      if (document.referrer) attribution.referrer = new URL(document.referrer).hostname;
      if (!attribution.utm_source) attribution.utm_source = document.referrer ? 'referencia' : 'directo';
      sessionStorage.setItem('renpat_attribution', JSON.stringify(attribution));
    }
  } catch { attribution = {}; }

  fetch('/api/config').then(response => {
    if (!response.ok) throw new Error('Configuración no disponible');
    return response.json();
  }).then(config => {
    if (!config.prelaunch) {
      if ($('#launch-strip')) $('#launch-strip').hidden = true;
      // This first release uses a manual inbox; do not promise automatic delivery.
      if ($('#preview-notice')) $('#preview-notice').textContent = 'Tu solicitud se guarda para revisión manual. La tarifa y la disponibilidad se confirman antes de contratar.';
    }
    if (typeof config.whatsapp === 'string' && /^[1-9]\d{7,14}$/.test(config.whatsapp)) {
      whatsappNumber = config.whatsapp;
      document.querySelectorAll('[data-whatsapp-contact]').forEach(link => {
        link.href = `https://wa.me/${whatsappNumber}?text=${encodeURIComponent(link.dataset.contactMessage)}`;
        link.hidden = false;
        link.addEventListener('click', () => events('whatsapp_click', { section: 'header' }));
      });
      if ($('#contact-method-whatsapp')) $('#contact-method-whatsapp').disabled = false;
      document.querySelectorAll('.whatsapp-link').forEach(link => {
        link.href = '#quote-form'; link.hidden = false;
        link.addEventListener('click', () => {
          $('#contact-method-whatsapp').checked = true;
          updateContactMethod();
          $('#contact-method-whatsapp').focus();
        });
      });
    }
    if (form) updateContactMethod();
    if (config.contactEmail && $('#contact-email')) {
      const anchor = document.createElement('a');
      anchor.href = `mailto:${config.contactEmail}`; anchor.textContent = config.contactEmail;
      $('#contact-email').replaceChildren(anchor); $('#contact-email').hidden = false;
      anchor.addEventListener('click', () => events('email_click'));
    }
    if (config.privacyEmail && $('#privacy-contact')) {
      const anchor = document.createElement('a'); anchor.href = `mailto:${config.privacyEmail}`; anchor.textContent = config.privacyEmail;
      $('#privacy-contact').textContent = 'Para solicitar acceso, corrección, cancelación u oposición al tratamiento de tus datos, escribe a ';
      $('#privacy-contact').append(anchor, '. Incluye el folio de tu solicitud cuando lo tengas.');
    }
  }).catch(() => { if (form) updateContactMethod(); });

  document.querySelectorAll('[data-destination]').forEach(link => link.addEventListener('click', () => {
    $('#origin').value = 'Guadalajara';
    $('#destination').value = link.dataset.destination;
    events('route_interest', { route: link.dataset.destination });
  }));
  if (!form) return;
  let submissionId = crypto.randomUUID();
  let lastPayload = null;
  let sending = false;
  const status = $('#form-status');
  const button = form.querySelector('button[type=submit]');
  const whatsappChoice = $('#contact-method-whatsapp');
  const whatsappLink = $('#form-whatsapp-link');
  const updateContactMethod = () => {
    const useWhatsapp = whatsappChoice.checked && !!whatsappNumber;
    button.firstElementChild.textContent = sending ? 'Enviando…' : useWhatsapp ? 'Enviar y abrir WhatsApp' : 'Enviar solicitud';
    $('#contact-method-help').textContent = useWhatsapp
      ? 'También enviaremos tu solicitud y confirmación por correo. Se abrirá WhatsApp con tus datos; sólo tendrás que pulsar Enviar.'
      : whatsappNumber ? 'Enviaremos tu solicitud y confirmación por correo.' : 'Enviaremos tu solicitud y confirmación por correo. WhatsApp no está disponible en este momento.';
  };
  form.querySelectorAll('[name=contactMethod]').forEach(choice => choice.addEventListener('change', updateContactMethod));
  whatsappLink.addEventListener('click', () => events('whatsapp_click', { section: 'quote' }));
  const whatsappUrl = (data, reference) => {
    const message = [
      'Hola, me gustaría cotizar un envío con RENPAT Logistics.',
      `Folio: ${reference}`, `Nombre: ${data.name.trim()}`, `Empresa: ${data.company.trim()}`,
      `Teléfono: ${data.phone.trim()}`, `Correo: ${data.email.trim()}`,
      `Origen: ${data.origin}`, `Destino: ${data.destination}`, `Peso estimado: ${data.weight} kg`,
      `Fecha de recolección: ${data.date}`, ...(data.notes.trim() ? [`Detalles de la carga: ${data.notes.trim()}`] : [])
    ].join('\n');
    return `https://wa.me/${whatsappNumber}?text=${encodeURIComponent(message)}`;
  };
  const displayErrors = errors => {
    form.querySelectorAll('[aria-invalid]').forEach(field => field.removeAttribute('aria-invalid'));
    form.querySelectorAll('.field-error').forEach(field => { field.textContent = ''; });
    for (const [key, value] of Object.entries(errors)) {
      const field = form.elements.namedItem(key);
      const message = document.getElementById(`error-${key}`);
      if (field && message) { field.setAttribute('aria-invalid', 'true'); field.setAttribute('aria-describedby', `error-${key}`); message.textContent = value; }
    }
  };
  form.addEventListener('submit', async event => {
    event.preventDefault();
    if (sending) return;
    displayErrors({});
    status.textContent = ''; status.className = 'form-status';
    const data = Object.fromEntries(new FormData(form));
    const useWhatsapp = data.contactMethod === 'whatsapp';
    // The contact choice does not change the email payload or its retry key.
    delete data.contactMethod;
    data.weight = Number(data.weight);
    data.consent = $('#consent').checked;
    data.attribution = attribution;
    const errors = {};
    for (const field of form.querySelectorAll('[required]')) {
      if (!field.checkValidity()) errors[field.name] = field.type === 'checkbox' ? 'Autoriza el uso de tus datos para continuar.' : 'Completa este campo con un valor válido.';
    }
    if (!data.email?.trim() || !$('#email').checkValidity()) errors.email = 'Ingresa un correo válido para recibir la confirmación.';
    if (data.origin === data.destination && data.origin !== 'Otra ciudad') errors.destination = 'El destino debe ser diferente al origen.';
    if ((data.origin === 'Otra ciudad' || data.destination === 'Otra ciudad') && !data.notes.trim()) errors.notes = 'Indica la ciudad y los detalles de tu ruta.';
    if (useWhatsapp && !whatsappNumber) errors.contactMethod = 'WhatsApp no está disponible. Selecciona contacto por correo.';
    if (Object.keys(errors).length) {
      displayErrors(errors);
      status.className = 'form-status error'; status.textContent = errors.contactMethod || 'Revisa los campos indicados antes de enviar.';
      form.querySelector('[aria-invalid=true]')?.focus(); return;
    }
    // An unchanged retry keeps its key after a timeout; edited submissions get a fresh key.
    const payload = JSON.stringify(data);
    if (lastPayload && payload !== lastPayload) submissionId = crypto.randomUUID();
    lastPayload = payload;
    data.submissionId = submissionId;
    whatsappLink.hidden = true; whatsappLink.removeAttribute('href');
    // Reserve the tab during the user gesture, before waiting for the email API.
    let whatsappTab = null;
    if (useWhatsapp) {
      try {
        whatsappTab = window.open('about:blank', '_blank');
        if (whatsappTab) {
          whatsappTab.opener = null;
          whatsappTab.document.title = 'Preparando tu solicitud | RENPAT';
          whatsappTab.document.body.textContent = 'Estamos enviando tu solicitud por correo. WhatsApp se abrirá al terminar.';
        }
      } catch { /* The saved-request link also works when new tabs are blocked. */ }
    }
    sending = true; button.disabled = true; button.firstElementChild.textContent = 'Enviando…';
    try {
      const response = await fetch('/api/leads', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data), signal: AbortSignal.timeout(15000) });
      const result = await response.json();
      if (!response.ok) {
        displayErrors(result.errors || {});
        throw new Error(result.message || 'No pudimos guardar tu solicitud. Intenta de nuevo.');
      }
      status.className = 'form-status success';
      status.textContent = `Solicitud guardada. Tu folio es ${result.reference}. La tarifa y la disponibilidad todavía deben confirmarse.`;
      if (result.confirmationStatus === 'accepted') status.textContent += ' Enviamos la confirmación a tu correo; revisa también la carpeta de spam.';
      else if (result.confirmationStatus === 'pending' || result.confirmationStatus === 'sending') status.textContent += ' La confirmación por correo está pendiente de envío. Conserva tu folio para dar seguimiento.';
      if (response.status === 201 && result.reference !== 'RECIBIDO') events('quote_submitted', { eventId: data.submissionId });
      if (useWhatsapp && result.reference !== 'RECIBIDO') {
        const url = whatsappUrl(data, result.reference);
        whatsappLink.href = url; whatsappLink.hidden = false;
        let opened = false;
        try {
          if (whatsappTab && !whatsappTab.closed) {
            whatsappTab.location.replace(url); opened = true;
            events('whatsapp_click', { section: 'quote' });
          }
        } catch { /* Keep the email success and the manual WhatsApp link. */ }
        status.textContent += opened
          ? ' Abrimos WhatsApp con tu solicitud preparada. Pulsa Enviar para compartirla.'
          : ' Pulsa «Abrir WhatsApp con mi solicitud» para abrir el mensaje preparado y enviarlo.';
      } else if (whatsappTab && !whatsappTab.closed) whatsappTab.close();
      form.reset(); $('#origin').value = 'Guadalajara';
      submissionId = crypto.randomUUID(); lastPayload = null;
      status.focus();
    } catch (error) {
      try { if (whatsappTab && !whatsappTab.closed) whatsappTab.close(); } catch { /* The visitor may have closed the tab. */ }
      status.className = 'form-status error';
      status.textContent = error.name === 'TimeoutError' || error instanceof TypeError ? 'No pudimos confirmar el envío. Tus datos siguen en el formulario. Reintenta; evitaremos duplicar una solicitud ya guardada.' : error.message;
      status.focus();
    } finally {
      sending = false; button.disabled = false; updateContactMethod();
    }
  });
})();

/* Portada 3D: el camión de RENPAT.
   Modelo hecho en Blender (geometría comprimida abajo) y dibujado con three.js.
   - Al cargar: la cámara se acomoda de perfil y aparece el botón de cotizar.
   - Con el scroll: el botón sube, la cámara rodea el camión, la pared de la
     caja se vuelve transparente y deja ver la carga, y el camión llega a un
     parque industrial con otros camiones.
   - Sin WebGL o con "reducir movimiento", queda la imagen fija del camión. */
(() => {
  'use strict';
  const root = document.querySelector('[data-ride]');
  const THREE = window.THREE;
  if (!root || !THREE || window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  const probe = document.createElement('canvas');
  if (!(probe.getContext('webgl2') || probe.getContext('webgl'))) return;
  // Si la vista no es una pantalla normal (por ejemplo, un marco que crece con la página), queda la imagen fija
  if (window.innerHeight > (window.screen && window.screen.height ? window.screen.height * 1.6 : 4000)) return;

  const MODEL = {"lo":[-10.15,-0.53,-1.62],"hi":[0.53,3.83,1.62],"parts":[{"g":"body","m":"alu","p":"","n":"","i":"","w":16},{"g":"body","m":"amber","p":"","n":"","i":"","w":16},{"g":"body","m":"black","p":"","n":"","i":"","w":16},{"g":"body","m":"box","p":"","n":"","i":"","w":16},{"g":"body","m":"bumper","p":"","n":"","i":"","w":16},{"g":"body","m":"chrome","p":"","n":"","i":"","w":16},{"g":"body","m":"dark","p":"","n":"","i":"","w":16},{"g":"body","m":"floor","p":"xZYZaTwdxZYZacPixZY2bTwdxZY2bcPi1gMZaTwd1gMZacPi1gM2bTwd1gM2bcPi","n":"Sbe3SbdJSUm3SUlJt7e3t7dJt0m3t0lJ","i":"BQABAAMABQADAAcABAAGAAIABAACAAAAAwACAAYAAwAGAAcABQAEAAAABQAAAAEAAQAAAAIAAQACAAMABwAGAAQABwAEAAUA","w":16},{"g":"body","m":"glass","p":"","n":"","i":"","w":16},{"g":"body","m":"lens","p":"","n":"","i":"","w":16},{"g":"body","m":"paint","p":"","n":"","i":"","w":16},{"g":"body","m":"red","p":"","n":"","i":"","w":16},{"g":"body","m":"seam","p":"","n":"t7dJt7e3t0lJt0m3t7dJt7e3t0lJt0m3t7dJt7e3t0lJt0m3t7dJt7e3t0lJt0m3SbdJSbe3SUlJSUm3t7dJt7e3t0lJt0m3SbdJSbe3SUlJSUm3SbdJSbe3SUlJSUm3SbdJSbe3SUlJSUm3SbdJSbe3SUlJSUm3","i":"","w":16},{"g":"cutaway","m":"boxskin","p":"xZY2bZrfxZY2bcPixZZd+JrfxZZd+MPi1gM2bZrf1gM2bcPi1gNd+Jrf1gNd+MPi","n":"Sbe3SbdJSUm3SUlJt7e3t7dJt0m3t0lJ","i":"BQABAAMABQADAAcABAAGAAIABAACAAAAAwACAAYAAwAGAAcABQAEAAAABQAAAAEAAQAAAAIAAQACAAMABwAGAAQABwAEAAUA","w":16},{"g":"cutaway","m":"seam","p":"","n":"t7dJt7e3t0lJt0m3t7dJt7e3t0lJt0m3t7dJt7e3t0lJt0m3t7dJt7e3t0lJt0m3SbdJSbe3SUlJSUm3t7dJt7e3t0lJt0m3SbdJSbe3SUlJSUm3SbdJSbe3SUlJSUm3SbdJSbe3SUlJSUm3SbdJSbe3SUlJSUm3","i":"","w":16},{"g":"wheel","m":"chrome","p":"","n":"","i":"","w":16},{"g":"wheel","m":"dark","p":"","n":"","i":"","w":16},{"g":"wheel","m":"rim","p":"","n":"","i":"","w":16},{"g":"wheel","m":"tire","p":"","n":"","i":"","w":16}]};
  const LOGO = 'data:image/png;base64,';
  const stage = root.querySelector('[data-ride-stage]');
  const canvas = root.querySelector('[data-ride-canvas]');
  const cta = root.querySelector('[data-ride-cta]');
  const captions = [...root.querySelectorAll('[data-ride-caption]')];
  const header = document.querySelector('.site-header');
  const clamp = (v, a = 0, b = 1) => Math.min(b, Math.max(a, v));
  const smooth = t => t * t * (3 - 2 * t);
  const isPhone = () => window.innerWidth <= 760;

  /* ---------- renderer, cielo, luz ---------- */
  // Los colores se escriben en sRGB (como en CSS); three.js los convierte a luz lineal
  if (THREE.ColorManagement) THREE.ColorManagement.legacyMode = false;
  let renderer;
  try {
    renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
  } catch (error) { return; }
  renderer.outputEncoding = THREE.sRGBEncoding;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.0;
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.VSMShadowMap;

  // Estilo "arcilla": fondo pastel de un solo tono, luz envolvente y sombras suaves
  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0xC4D9EF);   // fondo liso, del mismo tono que la neblina
  scene.fog = new THREE.Fog(0xC4D9EF, 90, 320);

  const pmrem = new THREE.PMREMGenerator(renderer);
  const studio = new THREE.Scene();
  studio.add(new THREE.Mesh(new THREE.SphereGeometry(50, 32, 16), new THREE.ShaderMaterial({
    side: THREE.BackSide,
    vertexShader: 'varying vec3 v; void main(){ v = normalize(position); gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }',
    fragmentShader: 'varying vec3 v; void main(){ float h = v.y; vec3 top = vec3(0.92,0.95,1.0); vec3 mid = vec3(0.88,0.91,0.95); vec3 low = vec3(0.62,0.66,0.72); vec3 c = h > 0.0 ? mix(mid, top, h) : mix(mid, low, clamp(-h*2.0,0.0,1.0)); gl_FragColor = vec4(c,1.0); }'
  })));
  scene.environment = pmrem.fromScene(studio, 0.08).texture;

  const hemi = new THREE.HemisphereLight(0xF6FAFF, 0x8FA9C6, 0.95);
  scene.add(hemi);
  const sun = new THREE.DirectionalLight(0xFFF3E6, 1.9);
  sun.castShadow = true;
  sun.shadow.bias = -0.0006;
  sun.shadow.radius = 9;
  sun.shadow.blurSamples = 16;
  sun.shadow.mapSize.set(isPhone() ? 1024 : 2048, isPhone() ? 1024 : 2048);
  scene.add(sun, sun.target);

  /* ---------- materiales mate ---------- */
  const std = (color, roughness, metalness = 0, extra = {}) => new THREE.MeshStandardMaterial({ color, roughness, metalness, envMapIntensity: 0.55, ...extra });
  const MAT = {
    paint: std(0xF6F7F8, 0.48),
    box: std(0xF1F4F6, 0.62),
    boxskin: std(0xF1F4F6, 0.62),
    alu: std(0xE2E7EC, 0.55),
    chrome: std(0xD5DCE3, 0.38, 0.25),
    black: std(0x353B43, 0.72),
    dark: std(0x414851, 0.7),
    bumper: std(0x58626D, 0.6),
    glass: std(0x9FB0C2, 0.28),
    lens: std(0xF3F6F8, 0.3),
    amber: std(0xF5A24E, 0.5, 0, { emissive: 0xF5A24E, emissiveIntensity: 0.25 }),
    red: std(0xE2645E, 0.5, 0, { emissive: 0xE2645E, emissiveIntensity: 0.2 }),
    tire: std(0x343A42, 0.86),
    rim: std(0xEDF0F3, 0.5),
    seam: std(0xE1E6EB, 0.6),
    floor: std(0xD6B892, 0.8)
  };
  // Pared cercana del camión principal: material propio para poder volverla transparente
  const SKIN = { boxskin: MAT.boxskin.clone(), seam: MAT.seam.clone() };
  Object.values(SKIN).forEach(m => { m.transparent = true; });

  const logoTex = new THREE.TextureLoader().load(LOGO, () => { dirty = true; });
  logoTex.encoding = THREE.sRGBEncoding;
  logoTex.anisotropy = renderer.capabilities.getMaxAnisotropy();
  const logoMat = () => new THREE.MeshBasicMaterial({ map: logoTex, color: 0xF2F2F2, transparent: true, toneMapped: false, depthWrite: false, polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -2 });
  const LOGO_FAR = logoMat();
  const LOGO_NEAR = logoMat();
  const logoGeo = new THREE.PlaneGeometry(4.6, 4.6 / 4);   // textura 2048×512 hecha desde el logo en vector

  /* ---------- geometría del modelo ---------- */
  const bytes = s => { const raw = atob(s); const out = new Uint8Array(raw.length); for (let i = 0; i < raw.length; i++) out[i] = raw.charCodeAt(i); return out; };
  const parts = { body: [], cutaway: [], wheel: [] };
  MODEL.parts.forEach(part => {
    const q = new Uint16Array(bytes(part.p).buffer);
    const pos = new Float32Array(q.length);
    for (let i = 0; i < q.length; i++) { const a = i % 3; pos[i] = MODEL.lo[a] + q[i] / 65535 * (MODEL.hi[a] - MODEL.lo[a]); }
    const n8 = new Int8Array(bytes(part.n).buffer);
    const nor = new Float32Array(n8.length);
    for (let i = 0; i < n8.length; i++) nor[i] = n8[i] / 127;
    const ib = bytes(part.i).buffer;
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    geo.setAttribute('normal', new THREE.BufferAttribute(nor, 3));
    geo.setIndex(new THREE.BufferAttribute(part.w === 32 ? new Uint32Array(ib) : new Uint16Array(ib), 1));
    geo.normalizeNormals();
    parts[part.g].push({ m: part.m, geo });
  });

  // Sombra de contacto: un degradado suave bajo cada camión
  const shadowCv = document.createElement('canvas'); shadowCv.width = 256; shadowCv.height = 64;
  const sh = shadowCv.getContext('2d');
  const sg = sh.createRadialGradient(128, 32, 4, 128, 32, 128);
  sg.addColorStop(0, 'rgba(12,22,40,0.55)'); sg.addColorStop(0.55, 'rgba(12,22,40,0.22)'); sg.addColorStop(1, 'rgba(12,22,40,0)');
  sh.setTransform(1, 0, 0, 0.25, 0, 24); sh.fillStyle = sg; sh.fillRect(0, -96, 256, 256);
  const shadowGeo = new THREE.PlaneGeometry(12.6, 3.9);
  const shadowMat = new THREE.MeshBasicMaterial({ map: new THREE.CanvasTexture(shadowCv), transparent: true, depthWrite: false, toneMapped: false });
  const TX = 5.05;                 // centra el camión en x = 0
  const WHEELS = [[-1.45 + TX, 0], [-8.10 + TX, 0], [-8.10 + TX, -0.36]];
  const meshOf = (geo, mat, shadows = true) => { const m = new THREE.Mesh(geo, mat); m.castShadow = shadows; m.receiveShadow = shadows; return m; };

  function makeTruck(main) {
    const truck = new THREE.Group();
    const body = new THREE.Group();
    truck.add(body);
    parts.body.forEach(({ m, geo }) => body.add(meshOf(geo, MAT[m] || MAT.dark)));
    const skin = new THREE.Group();
    // Orden fijo de lo semitransparente: carga (1), pared (2), logo (3); así nada parpadea según el ángulo
    parts.cutaway.forEach(({ m, geo }) => { const mesh = meshOf(geo, main ? SKIN[m] : MAT[m]); mesh.renderOrder = 2; skin.add(mesh); });
    body.add(skin);
    body.position.x = TX;
    const near = new THREE.Mesh(logoGeo, main ? LOGO_NEAR : LOGO_FAR);
    near.position.set(-6.92, 2.47, 1.284);
    const far = new THREE.Mesh(logoGeo, LOGO_FAR);
    far.position.set(-6.92, 2.47, -1.284); far.rotation.y = Math.PI;
    near.renderOrder = 3; far.renderOrder = 3;
    body.add(near, far);
    const wheels = [];
    WHEELS.forEach(([x, dz]) => [1, -1].forEach(side => {
      const w = new THREE.Group();
      parts.wheel.forEach(({ m, geo }) => w.add(meshOf(geo, MAT[m])));
      w.position.set(x, 0.52, dz * side);
      w.scale.z = side;
      truck.add(w); wheels.push(w);
    }));
    const blob = new THREE.Mesh(shadowGeo, shadowMat);
    blob.rotation.x = -Math.PI / 2; blob.position.set(0, 0.012, 0); blob.renderOrder = -1;
    truck.add(blob);
    return { truck, body, skin, wheels };
  }

  // Caja con esquinas redondeadas (estilo arcilla)
  const rbox = (w, h, d, r) => {
    r = Math.max(0.005, Math.min(r, w / 2 - 0.002, h / 2 - 0.002, d / 2 - 0.002));
    const b = r * 0.7, iw = w - 2 * b, ih = h - 2 * b, cr = Math.max(0.002, Math.min(r * 0.5, iw / 2 - 0.001, ih / 2 - 0.001));
    const s = new THREE.Shape();
    s.moveTo(-iw / 2 + cr, -ih / 2); s.lineTo(iw / 2 - cr, -ih / 2); s.quadraticCurveTo(iw / 2, -ih / 2, iw / 2, -ih / 2 + cr);
    s.lineTo(iw / 2, ih / 2 - cr); s.quadraticCurveTo(iw / 2, ih / 2, iw / 2 - cr, ih / 2);
    s.lineTo(-iw / 2 + cr, ih / 2); s.quadraticCurveTo(-iw / 2, ih / 2, -iw / 2, ih / 2 - cr);
    s.lineTo(-iw / 2, -ih / 2 + cr); s.quadraticCurveTo(-iw / 2, -ih / 2, -iw / 2 + cr, -ih / 2);
    const g = new THREE.ExtrudeGeometry(s, { depth: Math.max(0.001, d - 2 * b), bevelEnabled: true, bevelThickness: b, bevelSize: b, bevelSegments: 3, curveSegments: 4 });
    g.center(); g.computeVertexNormals();
    return g;
  };

  /* ---------- carga dentro de la caja ---------- */
  function makeCargo() {
    const cargo = new THREE.Group();
    const wood = std(0xC99A63, 0.8);
    const kraft = std(0xDDA868, 0.72);
    const film = std(0x2F80D2, 0.45, 0, { transparent: true, opacity: 0.62 });
    const pallets = [];
    for (let i = 0; i < 5; i++) for (const z of [-0.58, 0.58]) pallets.push([-9.35 + i * 1.19, z]);
    const palletMesh = new THREE.InstancedMesh(rbox(1.12, 0.14, 1.0, 0.03), wood, pallets.length);
    const cartons = new THREE.InstancedMesh(rbox(0.52, 0.44, 0.45, 0.05), kraft, pallets.length * 16);
    const wraps = [];
    const m4 = new THREE.Matrix4(), q = new THREE.Quaternion(), one = new THREE.Vector3(1, 1, 1), p = new THREE.Vector3();
    let c = 0, seed = 7;
    const rand = () => (seed = (seed * 16807) % 2147483647) / 2147483647;
    pallets.forEach(([x, z], i) => {
      m4.compose(p.set(x, 1.40, z), q, one); palletMesh.setMatrixAt(i, m4);
      const layers = 3 + (rand() > 0.45 ? 1 : 0);
      for (let l = 0; l < layers; l++) for (const ox of [-0.27, 0.27]) for (const oz of [-0.235, 0.235]) {
        if (l === layers - 1 && rand() > 0.82) continue;
        m4.compose(p.set(x + ox + (rand() - 0.5) * 0.02, 1.47 + 0.225 + l * 0.45, z + oz + (rand() - 0.5) * 0.02), q, one);
        cartons.setMatrixAt(c++, m4);
      }
      if (i % 3 === 1) wraps.push([x, z, layers]);
    });
    cartons.count = c;
    // Las cajas siempre se dibujan (si no, el navegador las oculta de golpe según un solo punto)
    [palletMesh, cartons].forEach(m => { m.castShadow = true; m.receiveShadow = true; m.frustumCulled = false; cargo.add(m); });
    wraps.forEach(([x, z, layers]) => {
      const h = layers * 0.45 + 0.05;
      const w = new THREE.Mesh(rbox(1.12, h, 1.0, 0.08), film);
      w.position.set(x, 1.47 + h / 2, z);
      w.renderOrder = 1;
      cargo.add(w);
    });
    return cargo;
  }

  /* ---------- parque industrial ---------- */
  const PARK_X = 18;               // dónde se estaciona el camión principal
  function makeWorld() {
    const world = new THREE.Group();
    const ground = new THREE.Mesh(new THREE.PlaneGeometry(900, 900), std(0xB3CDE9, 0.95));
    ground.rotation.x = -Math.PI / 2; ground.receiveShadow = true; world.add(ground);
    const flat = (w, d, color, x, z, y = 0.01, rough = 0.9) => {
      const m = new THREE.Mesh(new THREE.PlaneGeometry(w, d), std(color, rough));
      m.rotation.x = -Math.PI / 2; m.position.set(x, y, z); m.receiveShadow = true; world.add(m); return m;
    };
    flat(900, 9, 0x94B1D2, 150, 0, 0.02, 0.85);                        // carretera
    flat(900, 0.2, 0xF7FAFC, 150, 4.2, 0.03); flat(900, 0.2, 0xF7FAFC, 150, -4.2, 0.03);
    const dash = new THREE.InstancedMesh(new THREE.PlaneGeometry(3, 0.18), std(0xF7FAFC, 0.8), 140);
    const m4 = new THREE.Matrix4(), q = new THREE.Quaternion().setFromEuler(new THREE.Euler(-Math.PI / 2, 0, 0)), one = new THREE.Vector3(1, 1, 1), v = new THREE.Vector3();
    for (let i = 0; i < 140; i++) { m4.compose(v.set(-180 + i * 6, 0.03, 0), q, one); dash.setMatrixAt(i, m4); }
    dash.receiveShadow = true; world.add(dash);
    flat(130, 34, 0xC6DAF0, PARK_X + 18, -22, 0.015);                 // patio de maniobras

    const add = (geo, mat, x, y, z, cast = true) => { const m = new THREE.Mesh(geo, mat); m.position.set(x, y, z); m.castShadow = cast; m.receiveShadow = true; world.add(m); return m; };
    // Naves industriales con andenes
    const wall = std(0xF2F6FA, 0.7), navy = std(0x2C4670, 0.6), blue = std(0x2F80D2, 0.55), soft = std(0x4A5562, 0.7), canopyMat = std(0xCDD8E4, 0.6);
    const doorGeo = rbox(3.0, 3.4, 0.3, 0.14), canopyGeo = rbox(3.6, 0.22, 1.3, 0.09), bumperGeo = rbox(0.32, 0.52, 0.3, 0.1);
    const docks = [];
    [[PARK_X + 6, 40], [PARK_X + 52, 40]].forEach(([cx, w]) => {
      add(rbox(w, 8, 30, 0.7), wall, cx, 4, -42);
      add(rbox(w + 0.4, 0.7, 0.5, 0.25), blue, cx, 7.0, -26.9, false);
      add(rbox(w, 1.2, 2.4, 0.3), std(0xD9E5F2, 0.8), cx, 0.6, -26);
      for (let x = cx - w / 2 + 5; x <= cx + w / 2 - 4; x += 4.6) {
        add(doorGeo, navy, x, 2.6, -27.0, false);
        add(canopyGeo, canopyMat, x, 4.5, -26.4);
        [-1.3, 1.3].forEach(o => add(bumperGeo, soft, x + o, 1.0, -24.75, false));
        docks.push(x);
      }
    });
    // Postes de luz y árboles
    const poleMat = std(0xE6EEF6, 0.5);
    const poleGeo = new THREE.CylinderGeometry(0.12, 0.15, 9, 16), armGeo = rbox(0.2, 0.2, 2.3, 0.08), lampGeo = rbox(0.7, 0.18, 0.4, 0.08);
    const lampMat = std(0xFFFFFF, 0.4, 0, { emissive: 0xFFFFFF, emissiveIntensity: 0.3 });
    for (let x = PARK_X - 4; x < PARK_X + 120; x += 26) {
      add(poleGeo, poleMat, x, 4.5, -6.2);
      add(armGeo, poleMat, x, 8.9, -5.2, false);
      add(lampGeo, lampMat, x, 8.8, -4.2, false);
    }
    const leaf = std(0x86BE9E, 0.85), trunk = std(0xC3A88E, 0.85);
    const crownGeo = new THREE.SphereGeometry(1, 20, 14), stemGeo = new THREE.CylinderGeometry(0.16, 0.2, 2.4, 10);
    let seed = 11; const rand = () => (seed = (seed * 16807) % 2147483647) / 2147483647;
    for (let i = 0; i < 46; i++) {
      const x = 40 + i * 7.5 + rand() * 4, z = 9 + rand() * 26;
      if (x > PARK_X - 70 && x < PARK_X + 80 && z < 16) continue;
      const k = 1.5 + rand() * 1.1;
      const crown = add(crownGeo, leaf, x, 2.2 + k, z); crown.scale.set(k, k * 1.15, k);
      add(stemGeo, trunk, x, 1.2, z);
    }
    // Letrero de entrada
    const signCv = document.createElement('canvas'); signCv.width = 512; signCv.height = 160;
    const sg = signCv.getContext('2d'); sg.fillStyle = '#34507A'; sg.fillRect(0, 0, 512, 160);
    sg.fillStyle = '#3F92DE'; sg.fillRect(0, 138, 512, 22);
    sg.fillStyle = '#FFFFFF'; sg.font = '800 52px Overpass, Arial, sans-serif'; sg.textBaseline = 'middle';
    sg.fillText('PARQUE', 36, 50); sg.fillText('INDUSTRIAL', 36, 104);
    const signTex = new THREE.CanvasTexture(signCv); signTex.encoding = THREE.sRGBEncoding;
    add(rbox(5.4, 1.8, 0.4, 0.15), navy, PARK_X + 28, 2.7, -8.5);
    const face = new THREE.Mesh(new THREE.PlaneGeometry(5.0, 1.56), std(0xFFFFFF, 0.6, 0, { map: signTex }));
    face.position.set(PARK_X + 28, 2.7, -8.29); world.add(face);
    [-2.2, 2.2].forEach(o => add(rbox(0.3, 1.8, 0.3, 0.1), poleMat, PARK_X + 28 + o, 0.9, -8.5));
    return { world, docks };
  }

  /* ---------- armar la escena ---------- */
  const main = makeTruck(true);
  main.body.add(makeCargo());
  scene.add(main.truck);
  const { world, docks } = makeWorld();
  scene.add(world);
  // Otros camiones de RENPAT en los andenes, reculados
  [0, 4, 6, 9, 12].forEach(i => {
    const x = docks[i]; if (x === undefined) return;
    const t = makeTruck(false).truck;
    t.rotation.y = -Math.PI / 2;
    t.position.set(x, 0, -24.6 + 5.1);
    scene.add(t);
  });

  /* ---------- cámara y guion ---------- */
  const camera = new THREE.PerspectiveCamera(18, 1, 0.5, 600);
  // p: avance del scroll · az: giro (0 = de lado) · el: altura · d: distancia · t: a dónde mira (relativo al camión)
  const KEYS = [
    { p: 0.00, az: 0, el: 1.5, d: 0, fov: 18, t: [0, 1.9, 0] },
    { p: 0.16, az: 22, el: 9, d: 18, fov: 30, t: [0.4, 1.7, 0] },
    { p: 0.38, az: -20, el: 14, d: 19, fov: 34, t: [0.6, 1.8, 0] },
    { p: 0.68, az: -10, el: 18, d: 16, fov: 34, t: [-1.6, 2.0, 0] },
    { p: 1.00, az: -7, el: 18, d: 15, fov: 34, t: [-1.8, 2.0, 0] }
  ];
  const lerp = (a, b, t) => a + (b - a) * t;
  const catmull = (p0, p1, p2, p3, t) => 0.5 * ((2 * p1) + (-p0 + p2) * t + (2 * p0 - 5 * p1 + 4 * p2 - p3) * t * t + (-p0 + 3 * p1 - 3 * p2 + p3) * t * t * t);
  let fitD = 40;
  let narrowK = 1;   // en pantallas verticales la cámara se aleja para que quepa el camión
  const keyValue = (k, name, i) => name === 't' ? (i === 0 && narrowK > 1.4 ? k.t[0] * 0.35 : k.t[i]) : name === 'd' ? (k.d === 0 ? fitD : k.d * narrowK) : k[name];
  const sample = (p, name, i) => {
    let j = 0; while (j < KEYS.length - 2 && p > KEYS[j + 1].p) j++;
    const a = KEYS[Math.max(0, j - 1)], b = KEYS[j], c = KEYS[j + 1], d = KEYS[Math.min(KEYS.length - 1, j + 2)];
    const t = smooth(clamp((p - b.p) / (c.p - b.p)));
    return catmull(keyValue(a, name, i), keyValue(b, name, i), keyValue(c, name, i), keyValue(d, name, i), t);
  };

  // Recorrido del camión: quieto, luego arranca, avanza y se detiene en el parque
  const driveOf = p => PARK_X * (1 - Math.pow(1 - smooth(clamp(p)), 1.7));   // arranca suave y frena poco a poco hasta detenerse en p = 1
  const revealOf = p => smooth(clamp((p - 0.42) / 0.58));   // la caja se abre mientras el camión frena

  /* ---------- tamaño y encuadre ---------- */
  let W = 1, H = 1, headerH = 0;
  const resize = () => {
    // Siempre el tamaño real en pantalla del lienzo, para que nunca se estire ni se aplaste
    W = Math.max(1, Math.round(canvas.clientWidth || stage.clientWidth));
    H = Math.max(1, Math.round(canvas.clientHeight || stage.clientHeight));
    headerH = header ? header.offsetHeight : 0;
    const maxSide = Math.min(4096, renderer.capabilities.maxTextureSize || 4096);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, isPhone() ? 2.5 : 2, maxSide / Math.max(W, H)));
    renderer.setSize(W, H, false);
    camera.aspect = W / H;
    narrowK = clamp(1.05 / camera.aspect, 1, 2.4);
    // Distancia para que el camión de perfil quepa a lo ancho y deje aire arriba y abajo
    const v = THREE.MathUtils.degToRad(18) / 2;
    const h = Math.atan(Math.tan(v) * camera.aspect);
    const needW = isPhone() ? 10.8 : 13.6, needH = 4.4 / (isPhone() ? 0.5 : 0.56);
    fitD = Math.max(needW / 2 / Math.tan(h), needH / 2 / Math.tan(v));
    dirty = true;
  };

  /* ---------- bucle ---------- */
  let target = 0, shown = 0, intro = 0, dirty = true, running = false, last = performance.now(), introStart = 0;
  const readScroll = () => {
    const top = root.getBoundingClientRect().top;
    const span = root.offsetHeight - window.innerHeight;
    target = span > 0 ? clamp(-top / span) : 0;
  };
  const tmp = new THREE.Vector3();

  const frame = now => {
    if (!running) return;
    requestAnimationFrame(frame);
    if (Math.abs(canvas.clientWidth - W) > 1 || Math.abs(canvas.clientHeight - H) > 1) { resize(); readScroll(); }
    const dt = Math.min(0.05, (now - last) / 1000); last = now;
    const before = shown;
    shown += (target - shown) * (1 - Math.exp(-dt * 3.2));
    if (Math.abs(target - shown) < 0.00005) shown = target;
    const introK = introStart ? clamp((now - introStart) / 800) : 0;
    const settled = introK >= 1;
    if (!dirty && shown === before && settled && !idle) return;
    dirty = false;
    const p = shown;
    const ease = 1 - Math.pow(1 - introK, 4);

    // Camión
    const x = driveOf(p);
    main.truck.position.x = x;
    main.wheels.forEach(w => { w.rotation.z = -x / 0.52; });
    main.body.position.y = Math.abs(Math.sin(x * 1.7)) * 0.012 * clamp(x) * (x < PARK_X - 0.5 ? 1 : 0);
    const r = revealOf(p);
    SKIN.boxskin.opacity = 1 - r * 0.96; SKIN.seam.opacity = 1 - r;
    LOGO_NEAR.opacity = 1 - smooth(clamp(r * 1.6));
    [SKIN.boxskin, SKIN.seam].forEach(m => { m.depthWrite = r < 0.01; });

    // Cámara (con la entrada al cargar)
    const az = THREE.MathUtils.degToRad(sample(p, 'az') + (1 - ease) * 16);
    const el = THREE.MathUtils.degToRad(sample(p, 'el') - (1 - ease) * 3);
    const dist = sample(p, 'd') * (1 - (1 - ease) * 0.14);
    camera.fov = sample(p, 'fov');
    const shift = p < 0.2 ? (1 - p / 0.2) * fitD * Math.tan(THREE.MathUtils.degToRad(9)) * (isPhone() ? 0.06 : 0.1) : 0;
    tmp.set(x + sample(p, 't', 0), sample(p, 't', 1) - shift, sample(p, 't', 2));
    const sway = settled ? now / 1000 : 0;
    camera.position.set(
      tmp.x + dist * Math.sin(az) * Math.cos(el) + Math.sin(sway * 0.35) * 0.08,
      Math.max(0.6, tmp.y + dist * Math.sin(el) + Math.sin(sway * 0.5) * 0.04),
      tmp.z + dist * Math.cos(az) * Math.cos(el)
    );
    camera.lookAt(tmp);
    // Neblina: al inicio solo se ve el camión; al avanzar se disipa y aparece el parque
    const clear = smooth(clamp((p - 0.03) / 0.3));
    scene.fog.near = lerp(dist + 4, 90, clear);
    scene.fog.far = lerp(dist + 15, 320, clear);
    // Mientras hay texto, el encuadre se corre para dejarle espacio
    const room = captions.reduce((m, el) => {
      const [a, b] = el.dataset.rideCaption.split('-').map(Number);
      return Math.max(m, smooth(clamp((p - a + 0.04) / 0.06)) * (b >= 1 ? 1 : 1 - smooth(clamp((p - b + 0.02) / 0.06))));
    }, 0);
    if (isPhone()) camera.setViewOffset(W, H, 0, -H * 0.13 * room, W, H);
    else camera.setViewOffset(W, H, -W * 0.15 * room, 0, W, H);
    camera.updateProjectionMatrix();

    // Sol y sombras siguen al camión; el área crece al alejarse
    const span = p < 0.3 ? lerp(10, 24, smooth(clamp((p - 0.04) / 0.22))) : lerp(24, 14, smooth(clamp((p - 0.4) / 0.25)));
    const sc = sun.shadow.camera;
    sc.left = -span; sc.right = span; sc.top = span; sc.bottom = -span; sc.far = 160; sc.updateProjectionMatrix();
    sun.target.position.set(x - span * 0.2, 0, -span * 0.3);
    sun.position.set(sun.target.position.x - 10, 28, sun.target.position.z + 24);

    renderer.render(scene, camera);

    // Botón de cotizar: justo debajo del camión; con el scroll sube y se va
    tmp.set(x, -0.1, 1.3).project(camera);
    const below = (1 - tmp.y) / 2 * H;
    const lift = smooth(clamp(p / 0.12));
    cta.style.transform = `translate(-50%, ${(below + 22 - lift * (below - headerH + 40)).toFixed(1)}px)`;
    cta.style.opacity = (introK > 0.35 ? clamp((introK - 0.35) / 0.3) : 0) * (1 - smooth(clamp(p / 0.05)));
    cta.style.visibility = p > 0.05 ? 'hidden' : 'visible';
    captions.forEach(el => {
      const [a, b] = el.dataset.rideCaption.split('-').map(Number);
      el.classList.toggle('is-on', p >= a && p <= b);
    });
    root.style.setProperty('--ride', p.toFixed(4));
  };
  let idle = true;

  const start = () => { if (running) return; running = true; last = performance.now(); requestAnimationFrame(frame); };
  const stop = () => { running = false; };
  new IntersectionObserver(entries => { entries[0].isIntersecting ? start() : stop(); }).observe(root);
  document.addEventListener('visibilitychange', () => { document.hidden ? stop() : start(); });
  window.addEventListener('scroll', readScroll, { passive: true });
  let resizeTimer = null;
  window.addEventListener('resize', () => { clearTimeout(resizeTimer); resizeTimer = setTimeout(() => { resize(); readScroll(); }, 100); });
  if ('ResizeObserver' in window) new ResizeObserver(() => { resize(); readScroll(); }).observe(canvas);

  root.classList.add('is-live');
  resize(); readScroll();
  shown = target;
  introStart = target > 0.02 ? performance.now() - 3000 : performance.now() + 80;
  start();
  requestAnimationFrame(() => root.classList.add('is-ready'));
})();
/* Escena del mapa: portada + rutas.
   - Al cargar, las rutas se dibujan una vez.
   - El scroll vertical cede la portada y luego desliza las tarjetas de ruta
     en horizontal; la tarjeta activa resalta su ruta, su estado y su ciudad.
   - Los puntos de ida y vuelta avanzan solo mientras la persona hace scroll.
   - El selector de la portada resalta la ruta elegida y llena el formulario.
   - Sin JavaScript la escena se ve apilada; con "reducir movimiento", quieta. */
(() => {
  'use strict';
  const motion = window.matchMedia('(prefers-reduced-motion: reduce)');
  let reduced = motion.matches;
  const $ = selector => document.querySelector(selector);
  const scene = $('[data-scene]');

  if (scene) {
    const sticky = scene.querySelector('[data-scene-sticky]');
    const stage = scene.querySelector('[data-map-stage]');
    const rail = scene.querySelector('.rail');
    const track = scene.querySelector('[data-rail-track]');
    const anchor = scene.querySelector('.scene-anchor');
    const hero = scene.querySelector('.hero-copy');
    const routes = scene.querySelector('.routes-panel');
    const routesHead = scene.querySelector('.routes-head');
    const cards = [...track.querySelectorAll('.route-card')];
    const countLabel = scene.querySelector('[data-route-count]');
    const regionLabel = scene.querySelector('[data-route-region-name]');
    const states = [...stage.querySelectorAll('.state')];
    const cities = [...stage.querySelectorAll('.city')];
    const lines = [...stage.querySelectorAll('.route-line')].map(path => ({
      path, key: path.dataset.route, length: path.getTotalLength(),
      pulses: [...stage.querySelectorAll(`.pulse[data-route="${path.dataset.route}"]`)]
    }));
    const stateOf = Object.fromEntries(cards.map(card => [card.dataset.routeChapter, card.dataset.routeState]));
    let geo = null, shownKey = null, travel = 0, lastY = window.scrollY, drawn = reduced ? 1 : 0, pickedKey = '', frame = null;
    const clamp = value => Math.min(1, Math.max(0, value));
    const ease = value => { const t = clamp(value); return t * t * (3 - 2 * t); };

    const measure = () => {
      // Use the stable viewport height so mobile browser chrome does not move
      // the handoff while scrolling. Short screens retain the natural layout.
      scene.classList.toggle('is-live', !reduced);
      const vh = Math.max(1, Math.round(sticky.clientHeight || window.innerHeight));
      const mobile = window.innerWidth <= 860;
      const headerOffset = parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--header-offset')) || 84;
      const heroHeight = hero.offsetHeight;
      const mapRoom = vh - headerOffset - heroHeight - 40;
      const live = !reduced && (mobile ? mapRoom >= 96 : heroHeight + headerOffset + 64 <= vh);
      scene.classList.toggle('is-live', live);
      const mapHeight = Math.min(vh * .30, window.innerWidth * .72, Math.max(96, mapRoom));
      const contentTop = headerOffset + mapHeight + 16;
      sticky.style.setProperty('--map-height', `${mapHeight.toFixed(1)}px`);
      sticky.style.setProperty('--content-top', `${contentTop.toFixed(1)}px`);
      sticky.style.setProperty('--routes-rail-top', `${(contentTop + routesHead.offsetHeight + 22).toFixed(1)}px`);
      const style = getComputedStyle(rail);
      const padL = parseFloat(style.paddingLeft) || 0;
      const visible = Math.max(1, rail.clientWidth - padL - (parseFloat(style.paddingRight) || 0));
      const intro = Math.max(1, Math.round(vh * .65));
      const distance = Math.max(0, Math.round(track.scrollWidth - visible));
      const hold = Math.round(vh * .2);
      if (live) {
        scene.style.height = `${vh + intro + distance + hold}px`;
        // Compensate for the page's sticky-header scroll padding. #rutas lands
        // on fully revealed cards, rather than halfway through the crossfade.
        anchor.style.top = `${intro + headerOffset}px`;
        anchor.style.height = `${Math.max(1, distance + hold - headerOffset)}px`;
      } else {
        scene.style.removeProperty('height');
        anchor.style.top = `${routes.offsetTop}px`;
        anchor.style.height = `${routes.offsetHeight}px`;
      }
      geo = { live, vh, visible, intro, distance, padL, top: scene.getBoundingClientRect().top + window.scrollY };
    };

    // Resalta una ruta en el mapa (y su tarjeta, si la hay)
    const show = (key, cardIndex) => {
      if (key === shownKey && cardIndex === undefined) return;
      shownKey = key;
      const state = stateOf[key] || '';
      cards.forEach((el, i) => el.classList.toggle('is-active', i === cardIndex));
      lines.forEach(line => line.path.classList.toggle('is-active', line.key === key));
      states.forEach(el => el.classList.toggle('is-lit', !!state && el.dataset.state === state));
      cities.forEach(el => el.classList.toggle('is-dest', el.dataset.city === key));
      stage.dataset.active = key;
      const card = cards[cardIndex];
      if (card) {
        if (countLabel) countLabel.textContent = `${String(cardIndex + 1).padStart(2, '0')} / ${cards.length}`;
        if (regionLabel) regionLabel.textContent = card.dataset.routeRegion;
      }
    };

    const render = () => {
      frame = null;
      if (!geo) measure();
      const s = window.scrollY - geo.top;
      const t = geo.live ? clamp(s / geo.intro) : 0;
      const p = geo.live && geo.distance ? clamp((s - geo.intro) / geo.distance) : 0;
      const x = p * geo.distance;
      const heroOut = ease((t - .10) / .40);
      const routesIn = ease((t - .30) / .40);
      sticky.style.setProperty('--t', ease(t).toFixed(4));
      sticky.style.setProperty('--hero-out', heroOut.toFixed(4));
      sticky.style.setProperty('--routes-in', routesIn.toFixed(4));
      sticky.style.setProperty('--x', `${x.toFixed(1)}px`);
      sticky.style.setProperty('--p', p.toFixed(4));
      scene.dataset.phase = !geo.live ? 'static' : t < .30 ? 'hero' : t < .70 ? 'transition' : 'routes';
      hero.inert = geo.live && heroOut > .95;
      routes.inert = geo.live && routesIn < .90;
      if (reduced) drawn = 1;

      if (geo.live && routesIn >= .9 && cards.length) {
        // Both staggered rows share a real horizontal coordinate system.
        const trackLeft = track.getBoundingClientRect().left;
        const centers = cards.map(card => card.getBoundingClientRect().left - trackLeft + card.offsetWidth / 2);
        const startX = centers[0], endX = centers[centers.length - 1] - geo.distance;
        const focus = window.innerWidth <= 860 ? geo.visible / 2 : startX + (endX - startX) * p;
        let best = 0, bestGap = Infinity;
        centers.forEach((center, i) => {
          const gap = Math.abs(center - x - focus);
          if (gap < bestGap) { bestGap = gap; best = i; }
        });
        show(cards[best].dataset.routeChapter, best);
      } else {
        show(pickedKey, -1);
      }

      lines.forEach((line, index) => {
        line.path.style.strokeDasharray = `${line.length} ${line.length}`;
        line.path.style.strokeDashoffset = `${line.length * (1 - drawn)}`;
        const phase = travel / 1300 + index * 0.23;
        [reduced ? 0.4 : phase % 1, reduced ? 0.72 : 1 - ((phase + 0.5) % 1)].forEach((k, n) => {
          const pt = line.path.getPointAtLength(line.length * k);
          const pulse = line.pulses[n];
          pulse.setAttribute('cx', pt.x.toFixed(1));
          pulse.setAttribute('cy', pt.y.toFixed(1));
          pulse.style.opacity = drawn === 1 ? Math.min(1, Math.sin(Math.PI * k) * 2.2).toFixed(2) : '0';
        });
      });
    };
    const schedule = () => { if (frame === null) frame = requestAnimationFrame(render); };

    // Las rutas se dibujan cuando el mapa entra a la pantalla
    const drawRoutes = () => {
      const start = performance.now() + 150;
      const intro = now => {
        if (reduced) { drawn = 1; render(); return; }
        const k = Math.min(1, Math.max(0, (now - start) / 1600));
        drawn = 1 - Math.pow(1 - k, 3);
        render();
        if (k < 1) requestAnimationFrame(intro);
      };
      requestAnimationFrame(intro);
    };
    if (!reduced && 'IntersectionObserver' in window) {
      const watcher = new IntersectionObserver(entries => {
        if (!entries[0].isIntersecting) return;
        watcher.disconnect();
        drawRoutes();
      }, { rootMargin: '0px 0px -35% 0px' });
      watcher.observe(stage);
    } else if (!reduced) drawRoutes();

    window.addEventListener('scroll', () => {
      const y = window.scrollY;
      travel += Math.abs(y - lastY);
      lastY = y;
      schedule();
    }, { passive: true });
    const relayout = () => { geo = null; schedule(); };
    let resizeTimer = null;
    window.addEventListener('resize', () => { clearTimeout(resizeTimer); resizeTimer = setTimeout(relayout, 120); });
    window.addEventListener('load', relayout);
    if (document.fonts) document.fonts.ready.then(relayout);
    motion.addEventListener?.('change', event => { reduced = event.matches; relayout(); });

    // Keyboard focus follows the card's position, not its index across rows.
    // Pointer focus must not move a link between pointerdown and click.
    track.addEventListener('focusin', event => {
      const card = event.target.closest('.route-card');
      if (!card || !geo || !geo.live || !event.target.matches(':focus-visible')) return;
      const center = card.getBoundingClientRect().left - track.getBoundingClientRect().left + card.offsetWidth / 2;
      const x = Math.max(0, Math.min(geo.distance, center - geo.visible / 2));
      sticky.scrollLeft = 0;
      window.scrollTo({ top: geo.top + geo.intro + x, behavior: 'instant' });
    });

    // Selector de la portada: resalta la ruta elegida en el mapa
    const picker = $('[data-route-picker]');
    if (picker) {
      const destination = picker.querySelector('#rp-destination');
      destination.addEventListener('change', () => {
        const option = destination.selectedOptions[0];
        pickedKey = option && option.dataset.route ? option.dataset.route : '';
        schedule();
      });
    }

    measure();
    render();
  }

  /* ---------- Selector de ruta → formulario de cotización ---------- */
  const picker = $('[data-route-picker]');
  // Keep our generated destination separate from the visitor's cargo notes.
  let generatedDestinationNote = '';
  const updateDestinationNote = destination => {
    const notes = $('#notes');
    if (!notes) return;
    if (generatedDestinationNote) {
      const lines = notes.value.split('\n');
      const previous = lines.indexOf(generatedDestinationNote);
      if (previous !== -1) lines.splice(previous, 1);
      notes.value = lines.join('\n');
    }
    generatedDestinationNote = destination ? `Destino: ${destination}.` : '';
    if (generatedDestinationNote) {
      notes.value = generatedDestinationNote + (notes.value ? `\n${notes.value}` : '');
    }
  };
  const quoteForm = $('#quote-form');
  if (quoteForm) quoteForm.addEventListener('reset', () => { generatedDestinationNote = ''; });
  const mainDestination = $('#destination');
  if (mainDestination) mainDestination.addEventListener('change', () => updateDestinationNote(''));
  const fillForm = (origin, dest) => {
    const originSelect = $('#origin');
    const destSelect = $('#destination');
    if (!originSelect || !destSelect) return;
    const has = (select, value) => [...select.options].some(o => o.value === value || o.text === value);
    originSelect.value = has(originSelect, origin) ? origin : 'Otra ciudad';
    if (dest) {
      const supported = has(destSelect, dest);
      destSelect.value = supported ? dest : 'Otra ciudad';
      updateDestinationNote(supported ? '' : dest);
    }
  };
  if (picker) {
    const today = new Date();
    const iso = new Date(today.getTime() - today.getTimezoneOffset() * 60000).toISOString().slice(0, 10);
    const dateInput = picker.querySelector('#rp-date');
    dateInput.min = iso;
    picker.addEventListener('submit', event => {
      event.preventDefault();
      fillForm(picker.querySelector('#rp-origin').value, picker.querySelector('#rp-destination').value);
      const mainDate = $('#date');
      if (mainDate && dateInput.value) mainDate.value = dateInput.value;
      const quote = $('#quote-form');
      if (quote) quote.scrollIntoView({ behavior: reduced ? 'auto' : 'smooth' });
      const next = ['#destination', '#weight', '#date', '#name'].map(id => $(id)).find(el => el && !el.value);
      if (next) setTimeout(() => next.focus({ preventScroll: true }), reduced ? 0 : 700);
    });
  }

  // Supported cards also clear a previously generated custom destination.
  document.querySelectorAll('[data-destination]').forEach(link => link.addEventListener('click', () => {
    updateDestinationNote(link.dataset.destinationNote || '');
  }));

  /* ---------- Itinerario: el tramo se dibuja al llegar ---------- */
  const itinerary = $('[data-itinerary]');
  if (itinerary && !reduced && 'IntersectionObserver' in window) {
    const watcher = new IntersectionObserver(entries => {
      if (!entries[0].isIntersecting) return;
      itinerary.style.setProperty('--draw', '1');
      itinerary.classList.add('is-drawn');
      watcher.disconnect();
    }, { rootMargin: '0px 0px -25% 0px' });
    watcher.observe(itinerary);
  } else if (itinerary) {
    itinerary.style.setProperty('--draw', '1');
    itinerary.classList.add('is-drawn');
  }
})();
